add_action( 'enqueue_block_editor_assets', 'perfectpixel_disable_specific_blocks' );

function perfectpixel_disable_specific_blocks() {
	$blocks = array_values( array_filter( array_map( 'trim', explode( ',', '{{disabled_blocks}}' ) ) ) );
	if ( ! $blocks ) {
		return;
	}
	// Unregister in the browser, so blocks registered only by JavaScript are covered too.
	$js = 'wp.domReady( function () { ' . wp_json_encode( $blocks ) . '.forEach( function ( name ) { if ( wp.blocks.getBlockType( name ) ) { wp.blocks.unregisterBlockType( name ); } } ); } );';
	wp_add_inline_script( 'wp-blocks', $js );
}
